function text(name){try{const j=$(name).first().json||{};const v=j.body??j.data??j.response??j;return typeof v==='string'?v:JSON.stringify(v)}catch{return ''}}
function status(name){try{const j=$(name).first().json||{};return Number(j.statusCode||j.status||200)}catch{return 0}}
const home=text('HTTP — virya.music homepage'); const robots=text('HTTP — robots.txt'); const sitemap=text('HTTP — sitemap index'); const llms=text('HTTP — llms.txt');
const identity={
 homepage_ok:status('HTTP — virya.music homepage')>=200&&status('HTTP — virya.music homepage')<400,
 musicgroup_schema:/\"@type\"\s*:\s*\"MusicGroup\"/i.test(home),
 stable_entity_id:/https:\/\/www\.virya\.music\/#band/i.test(home),
 official_spotify:/6bbW0jOKAWJWm3h6CTWaAS/.test(home),
 official_instagram:/virya\.official/i.test(home),
 robots_sitemap:/Sitemap:\s*https:\/\/www\.virya\.music\/sitemap-index\.xml/i.test(robots),
 sitemap_ok:status('HTTP — sitemap index')>=200&&status('HTTP — sitemap index')<400&&/<urlset|<sitemapindex/i.test(sitemap),
 llms_ok:status('HTTP — llms.txt')>=200&&status('HTTP — llms.txt')<400&&/modern metal/i.test(llms)&&/Wrocław|Wroclaw/i.test(llms)&&/6bbW0jOKAWJWm3h6CTWaAS/.test(llms)
};
const queries=['VIRYA band','VIRYA metal Poland','VIRYA Wrocław','Echoes Of The Modern Mind VIRYA'];
const prompt=`Use Google Search grounding. Evaluate entity recognition for the music group VIRYA from Wrocław, Poland. Official source is https://www.virya.music/ and official Spotify artist id is 6bbW0jOKAWJWm3h6CTWaAS. For each query decide only: correct_band_mentioned boolean, official_domain_cited boolean, confusion string (empty if none), strongest_source string. Do not invent rankings or scores. Return JSON {checks:[...]}. Queries: ${JSON.stringify(queries)}`;
const gemini_body=JSON.stringify({contents:[{role:'user',parts:[{text:prompt}]}],tools:[{google_search:{}}],generationConfig:{temperature:0.1,maxOutputTokens:1800,responseMimeType:'application/json'}});
return [{json:{identity,queries,gemini_body}}];

const base=$('Build entity visibility check').first().json||{}; const identity=base.identity||{}; const response=$json||{};
let text='';try{text=(response.candidates?.[0]?.content?.parts||[]).map(p=>String(p.text||'')).join('').trim()}catch{};if(!text&&response.body){const b=response.body;text=typeof b==='string'?b:(b.candidates?.[0]?.content?.parts||[]).map(p=>String(p.text||'')).join('').trim()}
let parsed={};try{parsed=JSON.parse(String(text).replace(/```json|```/gi,'').trim())}catch{};const checks=Array.isArray(parsed.checks)?parsed.checks:[];
const recognized=checks.filter(x=>x?.correct_band_mentioned===true).length; const cited=checks.filter(x=>x?.official_domain_cited===true).length; const confusions=[...new Set(checks.map(x=>String(x?.confusion||'').trim()).filter(Boolean))];
const technical=[];if(!identity.musicgroup_schema||!identity.stable_entity_id)technical.push('schema MusicGroup/@id');if(!identity.robots_sitemap||!identity.sitemap_ok)technical.push('robots/sitemap');if(!identity.llms_ok)technical.push('llms.txt');
const actions=[];if(technical.length)actions.push(`Napraw first-party identity: ${technical.join(', ')}`);if(checks.length&&cited<Math.ceil(checks.length*0.75))actions.push('Wzmocnij zewnętrzne cytowania kierujące do virya.music/EPK zamiast produkować kolejne strony SEO');if(confusions.length)actions.push(`Doprecyzuj encję VIRYA w nowych publikacjach: ${confusions.slice(0,2).join(' / ')}`);
if(!actions.length)actions.push('Brak pilnej pracy SEO — publikuj realne newsy/koncerty i zdobywaj jakościowe wzmianki z linkiem do EPK.');
const content=`🔎 **VIRYA — entity visibility**\n\nFirst-party identity: **${technical.length?'WYMAGA UWAGI':'OK'}**\nGrounded search: poprawna VIRYA **${recognized}/${checks.length||'?'}**, virya.music cytowane **${cited}/${checks.length||'?'}**${confusions.length?`\nPomyłki: ${confusions.slice(0,2).join(' / ')}`:''}\n\n**Co ma sens zrobić:**\n${actions.slice(0,2).map((x,i)=>`${i+1}. ${x}`).join('\n')}`;
return [{json:{content,allowed_mentions:{parse:[]}}}];

